#!/usr/bin/env bash
# Every agent worktree belongs under `.worktrees/` in the main checkout
# (docs/agents/shared-checkout.md): the user's `Documents\` top level is
# personal files, and a 2026-10 run littered it with sibling checkouts
# because the doc itself prescribed `../<repo>-<agent>`. Registered trees
# are checked against that root; unregistered copies are caught by name too,
# since a hand-removed registration leaves the directory behind.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later
#
# Exit codes: 0 clean, 1 stray worktrees found, 125 not applicable (not
# inside a git checkout).
set -u

git rev-parse --show-toplevel >/dev/null 2>&1 || {
    printf 'SKIP  worktree hygiene (not inside a git checkout)\n'
    exit 125
}
common=$(git rev-parse --path-format=absolute --git-common-dir) || {
    printf 'SKIP  worktree hygiene (no git common dir)\n'
    exit 125
}
main=${common%/.git}
sanctioned="$main/.worktrees"
parent=${main%/*}
base=$(basename -- "$main")

bad=0
report_fix() {
    printf '      fix: mv "%s" "%s/<topic>" && git -C "%s" worktree repair ".worktrees/<topic>"\n' "$1" "$sanctioned" "$main"
    printf '      (or delete it: git -C "%s" worktree remove --force "%s")\n' "$main" "$1"
}

# Registered linked worktrees must sit under .worktrees/.
registered=$(git -C "$main" worktree list --porcelain | sed -n 's/^worktree //p')
while IFS= read -r path; do
    [ -n "$path" ] || continue
    case $path in
        "$main"|"$sanctioned"/*) ;;
        *)
            printf 'STRAY registered worktree outside .worktrees/: %s\n' "$path"
            report_fix "$path"
            bad=1
            ;;
    esac
done <<< "$registered"

# Unregistered copies: a sibling named <repo>-* that is itself a checkout
# (.git file or dir). The registration may be gone; the clutter is not.
shopt -s nullglob
for dir in "$parent/$base"-*/; do
    dir=${dir%/}
    [ -e "$dir/.git" ] || continue
    case $'\n'"$registered"$'\n' in *$'\n'"$dir"$'\n'*) continue ;; esac
    printf 'STRAY sibling checkout beside the main checkout: %s\n' "$dir"
    report_fix "$dir"
    bad=1
done

if [ "$bad" -ne 0 ]; then
    printf 'agent worktrees must live under %s (docs/agents/shared-checkout.md)\n' "$sanctioned"
    exit 1
fi
printf 'clean  every linked worktree lives under %s\n' "$sanctioned"
